import Aos from 'aos';
import React, { useEffect, useState } from 'react'
import { Swiper, SwiperSlide, useSwiper } from 'swiper/react';

export default function GetStarted() {
    const [swiper, setSwiper] = useState(null);
    const [currentIndex, setCurrentIndex] = useState(0);

    useEffect(function () {
        Aos.init({ duration: 2000 });
    }, []);

    const plyWoodData = [
        {
            image: 'assets/img/logo.svg'
        },
        {
            image: 'assets/img/logo.svg'
        }
    ]
    const goPrev = () => {
        if (swiper !== null) {
            swiper.slidePrev();
            if (currentIndex > 0) {
                setCurrentIndex(currentIndex - 1);
            }
        }
    };

    const goNext = () => {
        if (swiper !== null) {
            swiper.slideNext();
            if (currentIndex < plyWoodData.length) {
                setCurrentIndex(currentIndex + 1);
            }

        }
    };
    return (
        <>
            <section className="getStarted">
                <div className="container">
                    <div className="header">
                        <img src="assets/img/get-started.png" alt="" />
                    </div>
                    <div className="main__banner">
                        <h1>Better Materials.<br />Better Quality.</h1>
                    </div>
                </div>
                <div className="our__brands">
                    <div className="container">
                        <div className="row align-items-center">
                            <div className="col-md-6">
                                <h6>Our brands</h6>
                                <h2>Crafting wood into essentials that make life simpler.</h2>
                            </div>
                            <div className="col-md-6">
                                <Swiper
                                    autoHeight={true}
                                    onSwiper={(s) => {
                                        setSwiper(s);
                                    }}
                                >
                                    {
                                        plyWoodData.map((ele, i) => {
                                            return (
                                                <SwiperSlide key={i}>
                                                    <div className="brand__image">
                                                        <img src={ele.image} alt="" />
                                                    </div>
                                                </SwiperSlide>
                                            )
                                        })
                                    }

                                </Swiper>
                                <div className="navigation">
                                    <button className={`arrow-btn ${currentIndex === 0 ? 'disabled' : ''}`} onClick={goPrev}><img src="assets/img/products/left-arrow.svg" style={{ rotate: '180deg' }} alt="" /></button>
                                    <button className={`arrow-btn ${currentIndex === plyWoodData.length ? 'disabled' : ''}`} onClick={goNext}><img src="assets/img/products/right-arrow.svg" alt="" /></button>
                                </div>
                            </div>
                        </div>
                    </div>
                </div>
            </section>

        </>
    )
}
